from __future__ import annotations

import contextlib
import os
import threading
import time

from . import config

SLEEP_TIMEOUT = 0.001
LOCK_KEEP_ALIVE_TIMEOUT = 0.001 * 0.08
ALIVE_LOCK_REFRESH_INTERVAL_NS = 10_000_000_000
REMOVE_ORPHAN_LOCK_TIMEOUT = 20.0
AQUIRE_LOCK_TIMEOUT = 60.0


def os_touch(path: str) -> None:
	mode = 0o666
	flags = os.O_CREAT | os.O_WRONLY | os.O_EXCL
	file_descriptor = os.open(path, flags, mode)
	os.close(file_descriptor)


class LockFileMeta:
	__slots__ = ("ddb_dir", "name", "id", "time_ns", "stage", "mode", "path")

	def __init__(self, ddb_dir: str, name: str, id: str, time_ns: str | int, stage: str, mode: str) -> None:
		self.ddb_dir = ddb_dir
		self.name = name
		self.id = str(id)
		self.time_ns = str(time_ns)
		self.stage = stage
		self.mode = mode
		lock_file = f"{self.name}.{self.id}.{self.time_ns}.{self.stage}.{self.mode}.lock"
		self.path = os.path.join(self.ddb_dir, lock_file)

	def __repr__(self) -> str:
		return (
			"LockFileMeta("
			f"ddb_dir={self.ddb_dir!r}, name={self.name!r}, id={self.id!r}, "
			f"time_ns={self.time_ns!r}, stage={self.stage!r}, mode={self.mode!r})"
		)

	def new_with_updated_time(self) -> "LockFileMeta":
		return LockFileMeta(self.ddb_dir, self.name, self.id, time.time_ns(), self.stage, self.mode)


class FileLocksSnapshot:
	__slots__ = ("any_has_locks", "any_write_locks", "any_has_write_locks", "locks")

	def __init__(self, need_lock: LockFileMeta) -> None:
		self.locks = []
		self.any_has_locks = False
		self.any_write_locks = False
		self.any_has_write_locks = False

		if not os.path.isdir(need_lock.ddb_dir):
			return

		for file_name in os.listdir(need_lock.ddb_dir):
			if not file_name.endswith(".lock"):
				continue
			try:
				name, lock_id, time_ns, stage, mode, _ = file_name.split(".")
			except ValueError:
				continue
			if name != need_lock.name:
				continue

			lock_meta = LockFileMeta(need_lock.ddb_dir, name, lock_id, time_ns, stage, mode)

			if lock_meta.path != need_lock.path:
				lock_age = time.time_ns() - int(lock_meta.time_ns)
				if lock_age > REMOVE_ORPHAN_LOCK_TIMEOUT * 1_000_000_000:
					with contextlib.suppress(FileNotFoundError):
						os.unlink(lock_meta.path)
					continue

			self.locks.append(lock_meta)
			if lock_meta.stage == "has":
				self.any_has_locks = True
				if lock_meta.mode == "write":
					self.any_has_write_locks = True
			if lock_meta.mode == "write":
				self.any_write_locks = True

	def exists(self, lock_meta: LockFileMeta) -> bool:
		return any(
			existing.id == lock_meta.id and existing.stage == lock_meta.stage and existing.mode == lock_meta.mode
			for existing in self.locks
		)

	def oldest_need(self, need_lock: LockFileMeta) -> bool:
		need_locks = [lock for lock in self.locks if lock.stage == "need"]
		need_locks.sort(key=lambda lock: (int(lock.time_ns), int(lock.id)))
		return bool(need_locks) and need_locks[0].id == need_lock.id


class AbstractLock:
	__slots__ = ("db_name", "need_lock", "has_lock", "snapshot", "is_alive", "keep_alive_thread")

	mode: str

	def __init__(self, db_name: str) -> None:
		self.db_name = db_name.replace("/", "___").replace(".", "____")
		time_ns = time.time_ns()
		thread_id = str(threading.get_native_id())
		lock_dir = os.path.join(config.storage_directory, ".ddb")
		self.need_lock = LockFileMeta(lock_dir, self.db_name, thread_id, time_ns, "need", self.mode)
		self.has_lock = LockFileMeta(lock_dir, self.db_name, thread_id, time_ns, "has", self.mode)
		self.snapshot = FileLocksSnapshot(self.need_lock)
		self.is_alive = False
		self.keep_alive_thread = None
		os.makedirs(lock_dir, exist_ok=True)

	def _keep_alive_loop(self) -> None:
		current_has_lock_time_ns = int(self.has_lock.time_ns)
		while self.is_alive:
			time.sleep(LOCK_KEEP_ALIVE_TIMEOUT)
			if time.time_ns() - current_has_lock_time_ns < ALIVE_LOCK_REFRESH_INTERVAL_NS:
				continue
			new_has_lock = self.has_lock.new_with_updated_time()
			os_touch(new_has_lock.path)
			with contextlib.suppress(FileNotFoundError):
				os.unlink(self.has_lock.path)
			self.has_lock = new_has_lock
			current_has_lock_time_ns = int(new_has_lock.time_ns)

	def _start_keep_alive_thread(self) -> None:
		if self.keep_alive_thread is not None:
			raise RuntimeError("Keep alive thread already exists.")
		self.is_alive = True
		self.keep_alive_thread = threading.Thread(target=self._keep_alive_loop, daemon=False)
		self.keep_alive_thread.start()

	def _lock(self) -> None:
		raise NotImplementedError

	def _unlock(self) -> None:
		if self.keep_alive_thread is not None:
			self.is_alive = False
			self.keep_alive_thread.join()
			self.keep_alive_thread = None

		for attr in ("need_lock", "has_lock"):
			lock_meta = getattr(self, attr, None)
			if lock_meta is None:
				continue
			with contextlib.suppress(FileNotFoundError):
				os.unlink(lock_meta.path)
			setattr(self, attr, None)

	def __enter__(self):
		self._lock()
		return self

	def __exit__(self, exc_type, exc_val, exc_tb) -> None:
		self._unlock()


class ReadLock(AbstractLock):
	mode = "read"

	def _lock(self) -> None:
		os.makedirs(os.path.dirname(self.need_lock.path), exist_ok=True)
		os_touch(self.need_lock.path)
		self.snapshot = FileLocksSnapshot(self.need_lock)

		if self.snapshot.exists(self.has_lock):
			with contextlib.suppress(FileNotFoundError):
				os.unlink(self.need_lock.path)
			raise RuntimeError("Thread already has a read lock. Do not try to obtain a read lock twice.")

		start_time = time.time()
		try:
			while True:
				if not self.snapshot.any_write_locks or (
					not self.snapshot.any_has_write_locks and self.snapshot.oldest_need(self.need_lock)
				):
					self.has_lock = self.has_lock.new_with_updated_time()
					os_touch(self.has_lock.path)
					with contextlib.suppress(FileNotFoundError):
						os.unlink(self.need_lock.path)
					self._start_keep_alive_thread()
					return
				time.sleep(SLEEP_TIMEOUT)
				if time.time() - start_time > AQUIRE_LOCK_TIMEOUT:
					raise RuntimeError("Timeout while waiting for read lock.")
				self.snapshot = FileLocksSnapshot(self.need_lock)
		except BaseException:
			with contextlib.suppress(FileNotFoundError):
				os.unlink(self.need_lock.path)
			raise


class WriteLock(AbstractLock):
	mode = "write"

	def _lock(self) -> None:
		os.makedirs(os.path.dirname(self.need_lock.path), exist_ok=True)
		os_touch(self.need_lock.path)
		self.snapshot = FileLocksSnapshot(self.need_lock)

		if self.snapshot.exists(self.has_lock):
			with contextlib.suppress(FileNotFoundError):
				os.unlink(self.need_lock.path)
			raise RuntimeError("Thread already has a write lock. Do not try to obtain a write lock twice.")

		start_time = time.time()
		try:
			while True:
				if not self.snapshot.any_has_locks and self.snapshot.oldest_need(self.need_lock):
					self.has_lock = self.has_lock.new_with_updated_time()
					os_touch(self.has_lock.path)
					with contextlib.suppress(FileNotFoundError):
						os.unlink(self.need_lock.path)
					self._start_keep_alive_thread()
					return
				time.sleep(SLEEP_TIMEOUT)
				if time.time() - start_time > AQUIRE_LOCK_TIMEOUT:
					raise RuntimeError("Timeout while waiting for write lock.")
				self.snapshot = FileLocksSnapshot(self.need_lock)
		except BaseException:
			with contextlib.suppress(FileNotFoundError):
				os.unlink(self.need_lock.path)
			raise

