from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from typing import Any

import orjson

from . import config, indexing, io_bytes, utils


@dataclass(frozen=True)
class PartialDict:
	prefix: bytes
	key: str
	value: Any
	value_start: int
	value_end: int
	suffix: bytes


@dataclass(frozen=True)
class PartialFileHandle:
	db_name: str
	partial_dict: PartialDict
	indent_level: int
	indent_with: str
	indexer: indexing.Indexer
	full_data: dict


def deserialize_json_bytes(payload: bytes) -> Any:
	if config.use_orjson:
		return orjson.loads(payload)
	return json.loads(payload.decode("utf-8"))


def serialize_data_to_json_bytes(data: Any) -> bytes:
	if config.use_orjson:
		option = orjson.OPT_SORT_KEYS
		if config.indent:
			option |= orjson.OPT_INDENT_2
		return orjson.dumps(data, option=option)
	return json.dumps(data, indent=config.indent, sort_keys=True, ensure_ascii=False).encode("utf-8")


def _skip_json_whitespace(json_bytes: bytes, index: int) -> int:
	while index < len(json_bytes) and json_bytes[index] in (9, 10, 13, 32):
		index += 1
	return index


def read(db_name: str) -> Any:
	return deserialize_json_bytes(io_bytes.read(db_name))


def try_read_bytes_using_indexer(indexer: indexing.Indexer, db_name: str, key: str) -> bytes | None:
	if (index := indexer.get(key)) is None:
		return None
	start, end, _, _, value_hash = index
	partial_bytes = io_bytes.read(db_name, start=start, end=end)
	if value_hash != hashlib.sha256(partial_bytes).hexdigest():
		return None
	return partial_bytes


def partial_read(db_name: str, key: str) -> Any | None:
	indexer = indexing.Indexer(db_name)
	value_bytes = try_read_bytes_using_indexer(indexer, db_name, key)
	if value_bytes is not None:
		return deserialize_json_bytes(value_bytes)

	all_file_bytes = io_bytes.read(db_name)
	key_start, key_end = utils.find_outermost_key_in_json_bytes(all_file_bytes, key)
	if key_end == -1:
		return None

	start = _skip_json_whitespace(all_file_bytes, key_end)
	end = utils.seek_index_through_value_bytes(all_file_bytes, start)
	indent_level, indent_with = utils.detect_indentation_in_json_bytes(all_file_bytes, key_start)
	value_bytes = all_file_bytes[start:end]
	indexer.write(
		key=key,
		start_index=start,
		end_index=end,
		indent_level=indent_level,
		indent_with=indent_with,
		value_hash=hashlib.sha256(value_bytes).hexdigest(),
		old_value_end=end,
	)
	return deserialize_json_bytes(value_bytes)


def try_get_partial_file_handle_by_index(
	indexer: indexing.Indexer,
	db_name: str,
	key: str,
) -> tuple[PartialFileHandle | None, bytes | None]:
	value_bytes = try_read_bytes_using_indexer(indexer, db_name, key)
	if value_bytes is None:
		return None, io_bytes.read(db_name)

	all_file_bytes = io_bytes.read(db_name)
	key_start, key_end = utils.find_outermost_key_in_json_bytes(all_file_bytes, key)
	if key_end == -1:
		return None, all_file_bytes
	start = _skip_json_whitespace(all_file_bytes, key_end)
	end = utils.seek_index_through_value_bytes(all_file_bytes, start)
	indent_level, indent_with = utils.detect_indentation_in_json_bytes(all_file_bytes, key_start)
	partial_dict = PartialDict(all_file_bytes[:start], key, deserialize_json_bytes(value_bytes), start, end, all_file_bytes[end:])
	return (
		PartialFileHandle(
			db_name=db_name,
			partial_dict=partial_dict,
			indent_level=indent_level,
			indent_with=indent_with,
			indexer=indexer,
			full_data=deserialize_json_bytes(all_file_bytes),
		),
		None,
	)


def get_partial_file_handle(db_name: str, key: str) -> PartialFileHandle:
	indexer = indexing.Indexer(db_name)
	partial_handle, all_file_bytes = try_get_partial_file_handle_by_index(indexer, db_name, key)
	if partial_handle is not None:
		return partial_handle

	key_start, key_end = utils.find_outermost_key_in_json_bytes(all_file_bytes, key)
	if key_end == -1:
		raise KeyError(f'Key "{key}" not found in db "{db_name}"')

	start = _skip_json_whitespace(all_file_bytes, key_end)
	end = utils.seek_index_through_value_bytes(all_file_bytes, start)
	indent_level, indent_with = utils.detect_indentation_in_json_bytes(all_file_bytes, key_start)
	return PartialFileHandle(
		db_name=db_name,
		partial_dict=PartialDict(
			prefix=all_file_bytes[:start],
			key=key,
			value=deserialize_json_bytes(all_file_bytes[start:end]),
			value_start=start,
			value_end=end,
			suffix=all_file_bytes[end:],
		),
		indent_level=indent_level,
		indent_with=indent_with,
		indexer=indexer,
		full_data=deserialize_json_bytes(all_file_bytes),
	)


def write(db_name: str, data: Any) -> None:
	io_bytes.write(db_name, serialize_data_to_json_bytes(data))
	indexing.Indexer(db_name).clear()


def partial_write(partial_handle: PartialFileHandle) -> None:
	updated_data = partial_handle.full_data
	updated_data[partial_handle.partial_dict.key] = partial_handle.partial_dict.value
	data_bytes = serialize_data_to_json_bytes(updated_data)
	io_bytes.write(partial_handle.db_name, data_bytes)

	partial_handle.indexer.clear()
	key_start, key_end = utils.find_outermost_key_in_json_bytes(data_bytes, partial_handle.partial_dict.key)
	if key_end == -1:
		return
	start = _skip_json_whitespace(data_bytes, key_end)
	end = utils.seek_index_through_value_bytes(data_bytes, start)
	indent_level, indent_with = utils.detect_indentation_in_json_bytes(data_bytes, key_start)
	partial_handle.indexer.write(
		key=partial_handle.partial_dict.key,
		start_index=start,
		end_index=end,
		indent_level=indent_level,
		indent_with=indent_with,
		value_hash=hashlib.sha256(data_bytes[start:end]).hexdigest(),
		old_value_end=end,
	)

