from __future__ import annotations

from contextlib import contextmanager
from typing import Any, Callable, Generic, Tuple, TypeVar

from . import io_unsafe, locking, utils

T = TypeVar("T")


def type_cast(obj: Any, as_type):
	if as_type is None:
		return obj
	if as_type is str and not isinstance(obj, str):
		from .io_unsafe import serialize_data_to_json_bytes

		try:
			return serialize_data_to_json_bytes(obj).decode("utf-8")
		except TypeError:
			return str(obj)
	return as_type(obj)


class SessionBase:
	in_session: bool
	db_name: Any
	as_type: T
	write_lock: Any
	is_closed: bool

	def __init__(self, db_name: Any, as_type) -> None:
		self.in_session = False
		self.db_name = db_name
		self.as_type = as_type
		self.write_lock = None
		self.is_closed = True
		self.data_handle = {}

	def __enter__(self):
		self.in_session = True
		self.is_closed = False
		self.data_handle = {}
		return self

	def __exit__(self, exc_type, exc_value, traceback) -> None:
		write_lock = getattr(self, "write_lock", None)
		if write_lock is not None:
			if isinstance(write_lock, list):
				for lock in write_lock:
					lock._unlock()
			else:
				write_lock._unlock()
		self.write_lock = None
		self.in_session = False
		self.is_closed = True

	def close(self) -> None:
		if not self.is_closed:
			self.__exit__(None, None, None)

	def write(self) -> None:
		if not self.in_session:
			raise PermissionError("Only call write() inside a with statement.")


@contextmanager
def safe_context(super_obj, session_obj, *, db_names_to_lock=None):
	super_obj.__enter__()
	try:
		if isinstance(db_names_to_lock, str):
			session_obj.write_lock = locking.WriteLock(session_obj.db_name)
			session_obj.write_lock._lock()
		elif isinstance(db_names_to_lock, list):
			session_obj.write_lock = [locking.WriteLock(name) for name in session_obj.db_name]
			for lock in session_obj.write_lock:
				lock._lock()
		yield
	except BaseException as exc:
		super_obj.__exit__(type(exc), exc, exc.__traceback__)
		raise


class SessionFileFull(SessionBase, Generic[T]):
	def __enter__(self) -> Tuple["SessionFileFull", Any]:
		with safe_context(super(), self, db_names_to_lock=self.db_name):
			self.data_handle = io_unsafe.read(self.db_name)
			return self, type_cast(self.data_handle, self.as_type)

	def write(self) -> None:
		super().write()
		io_unsafe.write(self.db_name, self.data_handle)


class SessionFileKey(SessionBase, Generic[T]):
	def __init__(self, db_name: str, key: str, as_type):
		super().__init__(db_name, as_type)
		self.key = key
		self.partial_handle = None

	def __enter__(self) -> Tuple["SessionFileKey", Any]:
		with safe_context(super(), self, db_names_to_lock=self.db_name):
			self.partial_handle = io_unsafe.get_partial_file_handle(self.db_name, self.key)
			self.data_handle = self.partial_handle.partial_dict.value
			return self, type_cast(self.data_handle, self.as_type)

	def write(self) -> None:
		super().write()
		io_unsafe.partial_write(self.partial_handle)


class SessionFileWhere(SessionBase, Generic[T]):
