from __future__ import annotations

import os

from . import io_unsafe, locking, utils
from .indexing import Indexer


def read(file_name: str):
	info = utils.file_info(file_name)
	if not info.exists:
		return None

	with locking.ReadLock(file_name):
		return io_unsafe.read(file_name)


def partial_read(file_name: str, key: str):
	info = utils.file_info(file_name)
	if not info.exists:
		return None

	with locking.ReadLock(file_name):
		return io_unsafe.partial_read(file_name, key)


def write(file_name: str, data) -> None:
	os.makedirs(os.path.dirname(utils.file_info(file_name).json_path), exist_ok=True)
	with locking.WriteLock(file_name):
		io_unsafe.write(file_name, data)


def delete(file_name: str) -> None:
	info = utils.file_info(file_name)
	if not info.exists:
		return

	with locking.WriteLock(file_name):
		if info.json_exists and os.path.exists(info.json_path):
			os.remove(info.json_path)
		if info.ddb_exists and os.path.exists(info.ddb_path):
			os.remove(info.ddb_path)
		Indexer(file_name).clear()

