from __future__ import annotations

import os
import zlib

from . import config, utils


def read(db_name: str, *, start: int = None, end: int = None) -> bytes:
	"""
	Read raw bytes from a database file. Reads work regardless of the current
	compression setting by detecting the existing on-disk format.
	"""
	info = utils.file_info(db_name)

	if info.json_exists and info.ddb_exists:
		raise FileExistsError(f'Inconsistent: "{db_name}" exists as .json and .ddb. Please remove one of them.')

	if info.json_exists:
		with open(info.json_path, "rb") as file_handle:
			if start is None and end is None:
				return file_handle.read()
			start = 0 if start is None else start
			file_handle.seek(start)
			if end is None:
				return file_handle.read()
			return file_handle.read(end - start)

	if not info.ddb_exists:
		raise FileNotFoundError(f'No database file exists for "{db_name}"')

	with open(info.ddb_path, "rb") as file_handle:
		json_bytes = zlib.decompress(file_handle.read())
		if start is None and end is None:
			return json_bytes
		start = 0 if start is None else start
		end = len(json_bytes) if end is None else end
		return json_bytes[start:end]


def write(db_name: str, dump: bytes, *, start: int = None) -> None:
	"""
	Write raw bytes to a database file. Partial writes are only supported for
	uncompressed JSON files.
	"""
	if not isinstance(dump, (bytes, bytearray)):
		raise TypeError("dump must be bytes-like")

	info = utils.file_info(db_name)
	os.makedirs(os.path.dirname(info.json_path), exist_ok=True)

	remove_file = None
	payload = bytes(dump)

	if config.use_compression:
		if start is not None:
			raise RuntimeError("Cannot write to compressed file at a specific index")
		write_file = info.ddb_path
		if info.json_exists:
			remove_file = info.json_path
		payload = zlib.compress(payload, 1)
	else:
		write_file = info.json_path
		if info.ddb_exists:
			remove_file = info.ddb_path

	if start is None:
		with open(write_file, "wb") as file_handle:
			file_handle.write(payload)
	else:
		mode = "r+b" if os.path.exists(write_file) else "w+b"
		with open(write_file, mode) as file_handle:
			file_handle.seek(start)
			file_handle.truncate()
			file_handle.write(payload)

	if remove_file is not None and os.path.exists(remove_file):
		os.remove(remove_file)

