from __future__ import annotations

import os
from typing import Union

import orjson

from . import config


class Indexer:
	"""
	Manage the per-file top-level key index used for partial reads.
	"""

	__slots__ = ("data", "path")

	def __init__(self, db_name: str) -> None:
		safe_name = db_name.replace("/", "___")
		self.path = os.path.join(config.storage_directory, ".ddb", f"{safe_name}.index")
		os.makedirs(os.path.dirname(self.path), exist_ok=True)

		if not os.path.exists(self.path):
			self.data = {}
			return

		try:
			with open(self.path, "rb") as file_handle:
				self.data = orjson.loads(file_handle.read())
		except orjson.JSONDecodeError:
			self.data = {}

	def get(self, key: str) -> Union[list, None]:
		return self.data.get(key)

	def write(
		self,
		key: str,
		start_index: int,
		end_index: int,
		indent_level: int,
		indent_with: str,
		value_hash: str,
		old_value_end: int,
	) -> None:
		if self.data.get(key) is not None:
			delta = end_index - old_value_end
			for entry in self.data.values():
				if entry[0] > old_value_end:
					entry[0] += delta
					entry[1] += delta

		self.data[key] = [start_index, end_index, indent_level, indent_with, value_hash]
		with open(self.path, "wb") as file_handle:
			file_handle.write(orjson.dumps(self.data))

	def clear(self) -> None:
		self.data = {}
		if os.path.exists(self.path):
			os.remove(self.path)

