import random
import string


def _random_key(length: int = 8) -> str:
	return "".join(random.choice(string.ascii_lowercase) for _ in range(length))


def make_complex_nested_random_dict(depth: int, breadth: int):
	random.seed(1337)

	def make_value(level: int):
		if level <= 0:
			choices = [
				None,
				True,
				False,
				random.randint(-1000, 1000),
				random.random(),
				_random_key(12),
				[_random_key(4), random.randint(0, 10), {"x": _random_key(3)}],
			]
			return random.choice(choices)

		result = {}
		child_count = max(1, min(4, breadth))
		for _ in range(child_count):
			key = _random_key(6)
			if random.random() < 0.3:
				result[key] = [make_value(level - 1), make_value(level - 1)]
			else:
				result[key] = make_value(level - 1) if random.random() < 0.4 else make_dict(level - 1)
		return result

	def make_dict(level: int):
		result = {}
		child_count = max(1, min(4, breadth))
		for _ in range(child_count):
			result[_random_key(6)] = make_value(level - 1)
		return result

	return make_dict(max(1, min(depth, 4)))

