def _resolve_relative_path(db_name: str | os.PathLike) -> str:
	return os.path.join(config.storage_directory, _normalize_db_name(db_name))


def _get_storage_path(db_name: str | os.PathLike) -> str:
	info = file_info(db_name)
	if info.path is not None:
		return info.path
	return info.json_path if not config.use_compression else info.ddb_path


@dataclass(frozen=True)
class FileInfo:
	json_path: str
	json_exists: bool
	ddb_path: str
	ddb_exists: bool
	path: str | None
	exists: bool
	size_bytes: int | None
	created_time: datetime | None
	modified_time: datetime | None
	is_directory: bool
	is_file: bool

	def __iter__(self) -> Iterator[object]:
		yield self.json_path
		yield self.json_exists
		yield self.ddb_path
		yield self.ddb_exists


def file_info(db_name: str | os.PathLike) -> FileInfo:
	"""
	Return storage paths and availability details for a logical database name.
	The object can also be unpacked as:

	>>> json_path, json_exists, ddb_path, ddb_exists = file_info("users")
	"""
	base = _resolve_relative_path(db_name)
	json_path = f"{base}.json"
	ddb_path = f"{base}.ddb"
	json_exists = os.path.exists(json_path)
	ddb_exists = os.path.exists(ddb_path)
	path = json_path if json_exists else ddb_path if ddb_exists else None

	size_bytes = None
	created_time = None
	modified_time = None
	is_directory = False
	is_file = False
	if path is not None:
		stat = os.stat(path)
		size_bytes = stat.st_size
		created_time = datetime.fromtimestamp(stat.st_ctime)
		modified_time = datetime.fromtimestamp(stat.st_mtime)
		is_directory = os.path.isdir(path)
		is_file = os.path.isfile(path)

	return FileInfo(
		json_path=json_path,
		json_exists=json_exists,
		ddb_path=ddb_path,
		ddb_exists=ddb_exists,
		path=path,
		exists=json_exists or ddb_exists,
		size_bytes=size_bytes,
		created_time=created_time,
		modified_time=modified_time,
		is_directory=is_directory,
		is_file=is_file,
	)


def file_exists(db_name: str | os.PathLike) -> bool:
	return file_info(db_name).exists


def find_all(file_name: str | os.PathLike) -> list[str]:
	pattern = _normalize_db_name(file_name)
	files_all = glob.glob(os.path.join(config.storage_directory, f"{pattern}.ddb"))
	files_all += glob.glob(os.path.join(config.storage_directory, f"{pattern}.json"))
	files_all = sorted(set(os.path.normpath(path) for path in files_all))

	result = []
	for file_path in files_all:
		rel = os.path.relpath(file_path, config.storage_directory).replace("\\", "/")
		if rel.endswith(".ddb"):
			rel = rel[:-4]
		elif rel.endswith(".json"):
			rel = rel[:-5]
		result.append(rel)
	return result


def seek_index_through_value_bytes(json_bytes: bytes, index: int) -> int:
	"""
	Return the first byte index after the JSON value starting at `index`.
	"""
	list_depth = 0
	dict_depth = 0
	i = index
	len_json_bytes = len(json_bytes)

	while i < len_json_bytes:
		current = json_bytes[i]
		if current == byte_codes.BACKSLASH:
			i += 1
		elif current == byte_codes.QUOTE:
			while True:
				i = json_bytes.find(bytes([byte_codes.QUOTE]), i + 1)
				if i == -1:
					raise TypeError("Invalid JSON")
				j = i - 1
				backslash_count = 0
				while j >= 0 and json_bytes[j] == byte_codes.BACKSLASH:
					backslash_count += 1
					j -= 1
				if backslash_count % 2 == 0:
					break
			if list_depth == 0 and dict_depth == 0:
				return i + 1
		elif current == byte_codes.OPEN_SQUARE:
			list_depth += 1
		elif current == byte_codes.OPEN_CURLY:
			dict_depth += 1
		elif current == byte_codes.CLOSE_SQUARE:
			list_depth -= 1
			if list_depth == 0 and dict_depth <= 0:
				return i + 1 + dict_depth
		elif current == byte_codes.CLOSE_CURLY:
			dict_depth -= 1
			if dict_depth <= 0 and list_depth == 0:
				return i + 1 + dict_depth
		elif list_depth == 0:
			if dict_depth == -1:
				return i
			if dict_depth == 0 and current in (byte_codes.COMMA, byte_codes.NEWLINE):
				return i
		i += 1

	raise TypeError("Invalid JSON")


def count_nesting_in_bytes(json_bytes: bytes, start: int, end: int) -> int:
	i = start
	nesting = 0
	while (i := json_bytes.find(bytes([byte_codes.OPEN_CURLY]), i, end)) != -1:
		if i == 0 or json_bytes[i - 1] != byte_codes.BACKSLASH:
			nesting += 1
		i += 1
	i = start
	while (i := json_bytes.find(bytes([byte_codes.CLOSE_CURLY]), i, end)) != -1:
		if i == 0 or json_bytes[i - 1] != byte_codes.BACKSLASH:
			nesting -= 1
		i += 1
	return nesting


def find_outermost_key_in_json_bytes(json_bytes: bytes, key: str) -> Tuple[int, int]:
	key_bytes = f'"{key}":'.encode()

	if (curr_i := json_bytes.find(key_bytes, 0)) == -1:
		return (-1, -1)

	key_nest = [(curr_i, count_nesting_in_bytes(json_bytes, 0, curr_i))]

	while (next_i := json_bytes.find(key_bytes, curr_i + len(key_bytes))) != -1:
		nesting = count_nesting_in_bytes(json_bytes, curr_i + len(key_bytes), next_i)
		key_nest.append((next_i, nesting))
		curr_i = next_i

	if len(key_nest) == 1:
		index, level = key_nest[0]
		return (index, index + len(key_bytes)) if level == 1 else (-1, -1)

	for i in range(1, len(key_nest)):
		key_nest[i] = (key_nest[i][0], key_nest[i - 1][1] + key_nest[i][1])

	indices_at_level_one = [i for i, level in key_nest if level == 1]
	if len(indices_at_level_one) != 1:
		return (-1, -1)
	return (indices_at_level_one[0], indices_at_level_one[0] + len(key_bytes))


def detect_indentation_in_json_bytes(json_bytes: bytes, index: int) -> Tuple[int, str]:
	indentation_bytes = b""
	contains_tab = False
	for i in range(index - 1, -1, -1):
		if json_bytes[i] not in (byte_codes.SPACE, byte_codes.TAB):
			break
		if json_bytes[i] == byte_codes.TAB:
			contains_tab = True
		indentation_bytes += bytes([json_bytes[i]])

	if contains_tab:
		return len(indentation_bytes), "\t"
	if isinstance(config.indent, int) and config.indent > 0:
		return len(indentation_bytes) // config.indent, " " * config.indent
	if isinstance(config.indent, str) and config.indent:
		return len(indentation_bytes) // len(config.indent), config.indent
	return 0, ""

